test("上下左右それぞれ、直交する向きで重なる相手のうち最初に当たるものまでの線になる", () => {
  // 上は遠いほう（上下 -100〜-90）を先に並べ、近いほう（上下 10〜20）を選ぶことも見る
  const farAbove = { left: 50, top: -100, width: 20, height: 10 };
  const nearAbove = { left: 55, top: 10, width: 20, height: 10 };
  const below = { left: 60, top: 80, width: 30, height: 10 };
  const left = { left: 0, top: 45, width: 10, height: 20 };
  const right = { left: 120, top: 30, width: 10, height: 15 };

  expect(
    FacingDistances.createAmong({
      moved: Moved,
      others: [farAbove, nearAbove, below, left, right],
    }),
  ).toEqual({
    horizontal: {
      start: Option.some({
        along: SidePairs.Horizontal,
        at: 47.5,
        span: { min: 10, max: 50 },
      }),
      end: Option.some({
        along: SidePairs.Horizontal,
        at: 42.5,
        span: { min: 70, max: 120 },
      }),
    },
    vertical: {
      start: Option.some({
        along: SidePairs.Vertical,
        at: 62.5,
        span: { min: 20, max: 40 },
      }),
      end: Option.some({
        along: SidePairs.Vertical,
        at: 65,
        span: { min: 50, max: 80 },
      }),
    },
  });
});

test("右にだけ相手がいれば、他の 3 向きには線を引かない", () => {
  const right = { left: 120, top: 30, width: 10, height: 15 };

  expect(
    FacingDistances.createAmong({ moved: Moved, others: [right] }),
  ).toEqual({
    horizontal: {
      start: Option.none,
      end: Option.some({
        along: SidePairs.Horizontal,
        at: 42.5,
        span: { min: 70, max: 120 },
      }),
    },
    vertical: { start: Option.none, end: Option.none },
  });
});

test("直交する向きで接するだけの相手は相手にならない", () => {
  // 左右 70〜80 で、運んでいるものの右辺（70）に接するだけ
  const touchingAbove = { left: 70, top: 0, width: 10, height: 10 };

  expect(
    FacingDistances.createAmong({ moved: Moved, others: [touchingAbove] }),
  ).toEqual(FacingDistances.None);
});

test("運んでいるものと重なっている相手は相手にならず、その先の相手までの線になる", () => {
  const overlapping = { left: 40, top: 30, width: 20, height: 15 };
  const beyond = { left: 50, top: 0, width: 20, height: 10 };

  expect(
    FacingDistances.createAmong({
      moved: Moved,
      others: [overlapping, beyond],
    }).vertical.start,
  ).toEqual(
    Option.some({
      along: SidePairs.Vertical,
      at: 60,
      span: { min: 10, max: 40 },
    }),
  );
});

test("相手に接している向きには線を引かない", () => {
  // 接している相手を飛ばすと、その先の相手（上下 0〜10）までの線になる
  const touching = { left: 50, top: 30, width: 20, height: 10 };
  const beyond = { left: 50, top: 0, width: 20, height: 10 };

  expect(
    FacingDistances.createAmong({
      moved: Moved,
      others: [touching, beyond],
    }).vertical.start,
  ).toEqual(Option.none);
});

test("同じ距離に 2 つあれば、並びが先の相手までの線になる", () => {
  // 先の相手と重なる範囲は左右 50〜55、後の相手とは 65〜70（線の位置で見分ける）
  const first = { left: 45, top: 10, width: 10, height: 10 };
  const second = { left: 65, top: 10, width: 10, height: 10 };

  expect(
    FacingDistances.createAmong({
      moved: Moved,
      others: [first, second],
    }).vertical.start,
  ).toEqual(
    Option.some({
      along: SidePairs.Vertical,
      at: 52.5,
      span: { min: 20, max: 40 },
    }),
  );
});

test("測る回は、相手のいる向きに最初に当たる相手までの線が出る", () => {
  // 吸い付いたあとの右辺（400）から測る。吸い付く前（403）から測ると 403〜450 になる
  const dragging = moveSnapped(
    heldDrag(),
    pointerInputBy({ x: 103, y: 0 }, { measuresDistances: true }),
    { carried: HomeDrawn, others: [StationaryDrawn, RightDrawn] },
  );

  expect(ArtboardDrag.facingDistances(dragging).horizontal.end).toEqual(
    Option.some({
      along: SidePairs.Horizontal,
      at: 120,
      span: { min: 400, max: 450 },
    }),
  );
});

test("測らない回は、距離が出ない", () => {
  const dragging = moveSnapped(heldDrag(), pointerInputBy({ x: 103, y: 0 }), {
    carried: HomeDrawn,
    others: [StationaryDrawn, RightDrawn],
  });

  expect(ArtboardDrag.facingDistances(dragging)).toEqual(FacingDistances.None);
});

test("吸い付かない回は、吸い付かない位置から測る", () => {
  const dragging = moveSnapped(
    heldDrag(),
    pointerInputBy({ x: 103, y: 0 }, { snaps: false, measuresDistances: true }),
    { carried: HomeDrawn, others: [StationaryDrawn, RightDrawn] },
  );

  expect(ArtboardDrag.facingDistances(dragging).horizontal.end).toEqual(
    Option.some({
      along: SidePairs.Horizontal,
      at: 120,
      span: { min: 403, max: 450 },
    }),
  );
});

test("揃え先との隙間が同じ線を出している向きには距離を出さず、他の向きには出す", () => {
  /*
   * 左辺が 203 まで来て上の相手の左辺（200）へ 3px 寄り、左右 200〜400 になる。上の相手との
   * 隙間（上下 -50〜40）が同じ線を出すので上は除き、右の相手までは出す。
   */
  const above = { left: 200, top: -100, width: 100, height: 50 };
  const dragging = moveSnapped(
    heldDrag(),
    pointerInputBy({ x: 103, y: 0 }, { measuresDistances: true }),
    { carried: HomeDrawn, others: [above, RightDrawn] },
  );

  expect(ArtboardDrag.facingDistances(dragging)).toEqual({
    horizontal: {
      start: Option.none,
      end: Option.some({
        along: SidePairs.Horizontal,
        at: 120,
        span: { min: 400, max: 450 },
      }),
    },
    vertical: { start: Option.none, end: Option.none },
  });
});

test("Alt を押しながら運んでいる間、向きごとに最初に当たる他の artboard までの距離が出る", () => {
  renderCanvas({ selection: setupSelection() });
  drawnWithThirdBelow();

  // 左は `first` の右辺まで 32、下は `third` の上辺まで 160
  carrySecond({ x: 0, y: 100 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["160", "32"]);
});

test("倍率を上げて運んでいる間も、距離はドキュメント上の px で出る", () => {
  renderCanvas({ selection: setupSelection() });
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");

  /*
   * 1.2 倍で見ているときの描かれた矩形（`drawnWithThirdBelow` と同じ並びを 1.2 倍したもの）。
   * 動かすのは 1 回だけで、その間は描き直す前の実測が読まれるので固定の矩形でよい。
   */
  drawnAt("first", { left: 0, top: 0, width: 240, height: 168 });
  drawnAt("second", { left: 278.4, top: 0, width: 240, height: 168 });
  drawnAt("third", { left: 300, top: 480, width: 240, height: 168 });

  /*
   * 画面上で (0, 120) 運ぶと、左の `first` まで画面上で 38.4・ドキュメント上で 32、下の
   * `third` まで画面上で 192・ドキュメント上で 160。倍率を表示へ渡し忘れると画面上の値が出る。
   */
  carrySecond({ x: 0, y: 120 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["160", "32"]);
});

test("Alt を押さずに運んでいる間は、距離が出ない", () => {
  renderCanvas({ selection: setupSelection() });
  drawnWithThirdBelow();

  carrySecond({ x: 0, y: 100 });

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("Alt を押したままでも吸い付き、離すと吸い付いた位置の座標が書かれる", () => {
  const onRepositionArtboard = vi.fn();
  renderCanvas({ selection: setupSelection(), onRepositionArtboard });
  drawnFollowingFrames();

  // 左辺が `first` の右辺 200 を 3px 越えた位置（artboard-canvas.artboard-snap.test.tsx の 1 件目）
  dragSecond({ x: -29, y: 30 }, "alt");

  expect(onRepositionArtboard).toHaveBeenCalledWith("second", {
    x: 200,
    y: 30,
  });
});

test("Alt を押したままでも、揃え先との隙間の数値は変わらない", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  // 左辺が `first` の右辺 200 へ寄り、上下 200〜340。`first` の下辺 140 との隙間 60
  carrySecond({ x: -29, y: 200 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual(["60"]);
});

test("揃え先との隙間が同じ線を出している向きには、距離を出さず隙間だけを出す", () => {
  renderCanvas({ selection: setupSelection() });
  drawnAt("first", { left: 0, top: 0, width: 200, height: 140 });
  drawnFollowingFrame("second");
  drawnAt("third", { left: 464, top: 230, width: 200, height: 140 });

  /*
   * 左辺が `first` の左辺 0 へ寄り、左右 0〜200・上下 200〜340。上は `first` との隙間 60 が
   * 同じ線を出しているので距離を出さず、右の `third` の左辺までの 264 だけを出す。
   */
  carrySecond({ x: -229, y: 200 }, "alt");

  expect(distanceLabels("snap-gap")).toEqual(["60"]);
  expect(sortedFacingDistanceLabels()).toEqual(["264"]);
});

test("⌘ と Alt を一緒に押していると、吸い付かない位置から距離を測り、隙間は出ない", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  // 対照。Alt だけなら左辺が 200 へ寄って `first` に接し、右の `third` までの 64 だけが出る
  carrySecond({ x: -29, y: 30 }, "alt");
  expect(sortedFacingDistanceLabels()).toEqual(["64"]);

  // 同じ位置で ⌘ も押すと吸い付かず、左右 203〜403。左の `first` まで 3、右の `third` まで 61
  movePointer(artboardHandle("second"), { x: -29, y: 30 }, "meta+alt");

  expect(sortedFacingDistanceLabels()).toEqual(["3", "61"]);
  expect(distanceLabels("snap-gap")).toEqual([]);
});

test("まだ描かれていない（大きさの無い）artboard までは測らない", () => {
  renderCanvas({ selection: setupSelection() });
  drawnAt("first", { left: 0, top: 0, width: 200, height: 140 });
  drawnFollowingFrame("second");
  // 高さだけが 0。大きさで外さなければ、下の `third` まで 160 が出る
  drawnAt("third", { left: 250, top: 400, width: 200, height: 0 });

  carrySecond({ x: 0, y: 100 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["32"]);
});

test("Alt を離して動かし直すと、距離は消える", () => {
  renderCanvas({ selection: setupSelection() });
  drawnWithThirdBelow();

  carrySecond({ x: 0, y: 100 }, "alt");
  movePointer(artboardHandle("second"), { x: 0, y: 110 }, "none");

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("離すと距離は消える", () => {
  renderCanvas({ selection: setupSelection() });
  drawnWithThirdBelow();

  dragSecond({ x: 0, y: 100 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

function distanceLinesFrom(
  moved: CanvasBounds,
  targets: DistanceTargets,
): FacingDistances {
  switch (targets.kind) {
    case "within-parent":
      return FacingDistances.create({
        moved,
        parentBounds: targets.parentBounds,
        siblings: targets.siblings,
      });
    case "among-artboards":
      return FacingDistances.createAmong({ moved, others: targets.others });
  }
}

firstReached(
  facing: Facing,
  sweep: Readonly<{
    from: CanvasBounds;
    candidates: readonly CanvasBounds[];
  }>,
): Option<CanvasBounds> {
  const { from } = sweep;
  const ahead = sweep.candidates.filter((to) => {
    const isAhead =
      to !== from &&
      Facing.overlapsAcross(facing, { from, to }) &&
      Facing.distanceTo(facing, { from, to }) >= 0;
    return isAhead;
  });
  return ArrayEx.minBy(ahead, (to) =>
    Facing.distanceTo(facing, { from, to }),
  );
},
